// Handler creates http.Handler with routing matching OpenAPI spec.
func Handler(si ServerInterface) http.Handler {
	return HandlerWithOptions(si, ChiServerOptions{})
}

type ChiServerOptions struct {
	BaseURL          string
	BaseRouter       chi.Router
	Middlewares      []MiddlewareFunc
	ErrorHandlerFunc func(w http.ResponseWriter, r *http.Request, err error)
}

// HandlerFromMux creates http.Handler with routing matching OpenAPI spec based on the provided mux.
func HandlerFromMux(si ServerInterface, r chi.Router) http.Handler {
	return HandlerWithOptions(si, ChiServerOptions{
		BaseRouter: r,
	})
}

func HandlerFromMuxWithBaseURL(si ServerInterface, r chi.Router, baseURL string) http.Handler {
	return HandlerWithOptions(si, ChiServerOptions{
		BaseURL:    baseURL,
		BaseRouter: r,
	})
}

// HandlerWithOptions creates http.Handler with additional options
func HandlerWithOptions(si ServerInterface, options ChiServerOptions) http.Handler {
	r := options.BaseRouter

	if r == nil {
		r = chi.NewRouter()
	}
	if options.ErrorHandlerFunc == nil {
		options.ErrorHandlerFunc = func(w http.ResponseWriter, r *http.Request, err error) {
			http.Error(w, err.Error(), http.StatusBadRequest)
		}
	}
	wrapper := ServerInterfaceWrapper{
		Handler:            si,
		HandlerMiddlewares: options.Middlewares,
		ErrorHandlerFunc:   options.ErrorHandlerFunc,
	}

	r.Group(func(r chi.Router) {
		r.Get(options.BaseURL+"/health", wrapper.GetHealth)
	})
	r.Group(func(r chi.Router) {
		r.Post(options.BaseURL+"/auth/login", wrapper.Login)
	})
	r.Group(func(r chi.Router) {
		r.Post(options.BaseURL+"/auth/logout", wrapper.Logout)
	})
	r.Group(func(r chi.Router) {
		r.Get(options.BaseURL+"/auth/session", wrapper.GetSession)
	})
	r.Group(func(r chi.Router) {
		r.Get(options.BaseURL+"/inquiries", wrapper.ListInquiries)
	})
	r.Group(func(r chi.Router) {
		r.Post(options.BaseURL+"/inquiries", wrapper.CreateInquiry)
	})
	r.Group(func(r chi.Router) {
		r.Get(options.BaseURL+"/inquiries/{id}", wrapper.GetInquiry)
	})
	r.Group(func(r chi.Router) {
		r.Post(options.BaseURL+"/inquiries/{id}/runs", wrapper.CreateRun)
	})
	r.Group(func(r chi.Router) {
		r.Get(options.BaseURL+"/runs/{id}", wrapper.GetRun)
	})
	r.Group(func(r chi.Router) {
		r.Get(options.BaseURL+"/drafts/{id}", wrapper.GetDraft)
	})
	r.Group(func(r chi.Router) {
		r.Post(options.BaseURL+"/drafts/{id}/revisions", wrapper.CreateDraftRevision)
	})
	r.Group(func(r chi.Router) {
		r.Post(options.BaseURL+"/drafts/{id}/approve", wrapper.ApproveDraft)
	})
	r.Group(func(r chi.Router) {
		r.Post(options.BaseURL+"/drafts/{id}/reject", wrapper.RejectDraft)
	})
	r.Group(func(r chi.Router) {
		r.Get(options.BaseURL+"/tickets", wrapper.ListTickets)
	})
	r.Group(func(r chi.Router) {
		r.Get(options.BaseURL+"/outbox", wrapper.ListOutbox)
	})
	r.Group(func(r chi.Router) {
		r.Get(options.BaseURL+"/kb/articles", wrapper.ListKbArticles)
	})
	r.Group(func(r chi.Router) {
		r.Post(options.BaseURL+"/kb/articles", wrapper.CreateKbArticle)
	})
	r.Group(func(r chi.Router) {
		r.Patch(options.BaseURL+"/kb/articles/{id}", wrapper.UpdateKbArticle)
	})
	r.Group(func(r chi.Router) {
		r.Post(options.BaseURL+"/kb/reindex", wrapper.ReindexKb)
	})
	r.Group(func(r chi.Router) {
		r.Get(options.BaseURL+"/evals/runs", wrapper.ListEvalRuns)
	})
	r.Group(func(r chi.Router) {
		r.Get(options.BaseURL+"/evals/runs/{id}", wrapper.GetEvalRun)
	})
	r.Group(func(r chi.Router) {
		r.Get(options.BaseURL+"/audit", wrapper.ListAudit)
	})

	return r
}
